    different = gc_calls(cf_function("void different("))[0]
    uid = different["args"][0]["type"].removeprefix("ptr:")
    assert uid != bid and different["callee"] == cf_member(uid, "void")["name"]
    assert cf_records[uid]["fields"][1]["type"] == "uint"
